import assert from 'node:assert/strict';
import { spawn, execFile } from 'node:child_process';
import {promisify} from 'node:util';
import { mkdir, readFile, writeFile } from 'node:fs/promises';
import { createWriteStream } from 'node:fs';
import path from 'node:path';
import { parse } from 'yaml';

// Invokes the external Builder's actual build/deploy entrypoint. No Result,
// Runtime evidence or model responses are generated by this test driver.
export function liveTaskBuilder({directory, port, python, modelConfig}) {
  const exec=promisify(execFile),distro=process.env.MIGRATION_LIVE_BUILDER_WSL;
  const hostPath=p=>distro ? p.replace(/^([A-Za-z]):/,(_,drive)=>'/mnt/'+drive.toLowerCase()).replaceAll('\\','/') : p;
  const wsl=args=>exec('wsl.exe',['-d',distro,'-u','root','--',...args],{windowsHide:true,maxBuffer:4*1024*1024});
  const root = process.env.MIGRATION_LIVE_BUILDER_ROOT;
  const hostPython = process.env.MIGRATION_LIVE_BUILDER_PYTHON;
  assert(root && hostPython, 'Configure real Builder root and host Python');
  const baseUrl = process.env.BUNDLE_LIVE_BUILDER_URL ?? `http://127.0.0.1:${port}/oj/`;
  const trust = [{reference:'real-builder', label:'真实 Finance Solution Builder', baseUrlPrefix:baseUrl, credentialEnv:'LIVE_BUILDER_TOKEN'}];
  const builds=[];
  let active;
  async function close() {
    if (!active) return;
    if(active.child.exitCode===null){
      if(distro)await wsl(['/usr/sbin/runuser','-u','finance-eval','--','touch',active.nativeState+'/stop']);
      else await writeFile(path.join(active.state,'stop'),'stop');
      await Promise.race([active.exit, new Promise((_,reject)=>setTimeout(()=>reject(new Error('Builder cleanup timed out')),30000).unref())]);
    }
    if(distro)await wsl(['cp','-R',active.nativeState+'/.',hostPath(active.state)]);
    active.log.end(); active=null;
  }
  async function bind(page) {
    await close();
    const round=path.join(directory,'builder-'+builds.length);
    await mkdir(round,{recursive:true});
    const download=page.waitForEvent('download');
    await page.getByRole('button',{name:'生成并下载 Builder 需求',exact:true}).click();
    await (await download).saveAs(path.join(round,'requirements.yaml'));
    const requirements=parse(await readFile(path.join(round,'requirements.yaml'),'utf8'));
    assert.equal(requirements.schemaVersion,'finance.runtime-build-requirements.v2');
    assert.equal(requirements.target.protocols.instance,'finance.skill-eval.runtime-instance.v2');
    await writeFile(path.join(round,'requirements.json'),JSON.stringify(requirements));
    const source=page.waitForEvent('download');
    await page.getByRole('button',{name:'下载绑定的 Skill 与依赖',exact:true}).click();
    await (await source).saveAs(path.join(round,'skills.json'));
    const skillSet=JSON.parse(await readFile(path.join(round,'skills.json'),'utf8'));
    assert.equal(skillSet.skills.length,requirements.extensions.migrationTask.skills.length);
    assert(!('bundle' in skillSet) && !('archiveBase64' in skillSet));
    const state=path.join(round,'state'), log=createWriteStream(path.join(round,'builder.log'));
    const nativeState=distro ? (process.env.MIGRATION_LIVE_BUILDER_STATE_ROOT??'/var/lib/finance-builder/builds')+'/'+path.basename(directory)+'-'+builds.length : state;
    if(distro)await mkdir(state,{recursive:true});
    const args=[root.replaceAll('\\','/')+'/engineering/build_migration_task.py',
      '--requirements',hostPath(path.join(round,'requirements.json')),'--skills',hostPath(path.join(round,'skills.json')),
      '--state-root',nativeState,'--python',python,'--model-config',process.env.MIGRATION_LIVE_BUILDER_MODEL_CONFIG??modelConfig,'--port',String(port)];
    if(process.env.MIGRATION_LIVE_BUILDER_CREDENTIAL_FILE)args.push('--credential-file',process.env.MIGRATION_LIVE_BUILDER_CREDENTIAL_FILE);
    if(process.env.MIGRATION_LIVE_BUILDER_ENV_FILE)args.push('--env-file',process.env.MIGRATION_LIVE_BUILDER_ENV_FILE);
    const child=spawn(distro?'wsl.exe':hostPython,distro?['-d',distro,'-u','root','--','/usr/sbin/runuser','-u','finance-eval','--',hostPython,...args]:args,
      {cwd:distro?process.cwd():root,windowsHide:true,env:{...process.env,PYTHONUTF8:'1',PYTHONUNBUFFERED:'1'},stdio:['ignore','pipe','pipe']});
    child.stdout.pipe(log); child.stderr.pipe(log);
    const exit=new Promise(resolve=>child.once('exit',resolve));
    active={state,nativeState,log,child,exit};
    const deadline=Date.now()+15*60*1000;
    let info;
    while(Date.now()<deadline) {
      assert.equal(child.exitCode,null,'Real Builder exited; inspect retained builder.log');
      info=await (distro?wsl(['cat',nativeState+'/connection-info.json']).then(r=>r.stdout):readFile(path.join(state,'connection-info.json'),'utf8')).then(JSON.parse).catch(()=>null);
      if(info)break;
      await new Promise(resolve=>setTimeout(resolve,1500));
    }
    assert.equal(info?.status,'READY','Real Builder build exceeded deadline');
    assert.equal(info.baseUrl,baseUrl);
    if(distro)await wsl(['cp','-R',nativeState+'/.',hostPath(state)]);
    if(process.env.BUNDLE_LIVE_SERVICE_URL)assert(process.env.LIVE_BUILDER_TOKEN===info.token,'Deployed API and Builder credential configuration must match');
    process.env.LIVE_BUILDER_TOKEN=info.token;
    const result=JSON.parse(await readFile(path.join(state,'result.json'),'utf8'));
    const buildHost=await readFile(path.join(state,'build-host.json'),'utf8').then(JSON.parse);
    assert.equal(buildHost.platform,distro?'Linux':process.platform==='win32'?'Windows':'Linux');
    assert.equal(result.status,'SUCCEEDED');
    assert.equal(result.schemaVersion,'finance.runtime-build-result.v2');
    builds.push({buildId:result.buildId,requestId:result.requestId,deploymentId:result.launcher.deploymentId,buildHost,
      skillCount:skillSet.skills.length,assetCount:Object.keys(skillSet.assets??{}).length,instanceProtocol:requirements.target.protocols.instance,artifactSha256:result.launcher.artifactSha256,resultDigest:result.resultDigest,candidateId:requirements.source.assetId});
    await page.getByLabel('导入 Builder Result JSON',{exact:true}).setInputFiles(path.join(state,'result.json'));
    await page.getByLabel('Builder 交付信任引用',{exact:true}).selectOption('real-builder');
    const accepted=page.waitForResponse(r=>r.url().endsWith('/runtime-deliveries')&&r.request().method()==='POST',{timeout:900000});
    await page.getByRole('button',{name:'验证并绑定 Builder 交付',exact:true}).click();
    const response=await accepted;
    assert.equal(response.status(),200,await response.text());
    const capabilities=await fetch(baseUrl+'v1/runtime-capabilities',{headers:{authorization:'Bearer '+info.token}}).then(r=>r.json());
    assert(capabilities.features.multiSkill);
    return capabilities;
  }
  return {baseUrl,trust,builds,bind,close};
}
